sys_variable_value.value:
(function execute(inputs, outputs) {

    var deadline = new GlideDateTime(inputs.response_window_until);
    var now = new GlideDateTime();

    outputs.is_expired = (now.getNumericValue() >= deadline.getNumericValue());

})(inputs, outputs);

